SELECT '1. update_order_referral_code_v1 存在、SECURITY DEFINER、固定 search_path' AS 項目, (SELECT p.prosecdef AND array_to_string(p.proconfig, ',') LIKE '%search_path=pg_catalog, public%' FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)')) AS 結果
UNION ALL SELECT '2. authenticated、service_role 可執行', has_function_privilege('authenticated', to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'), 'EXECUTE') AND has_function_privilege('service_role', to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'), 'EXECUTE')
UNION ALL SELECT '3. anon、PUBLIC 不在授權清單', (SELECT array_to_string(p.proacl, ',') NOT LIKE '%anon=%' AND array_to_string(p.proacl, ',') NOT LIKE '%,=X/%' AND array_to_string(p.proacl, ',') NOT LIKE '=X/%' FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'))
UNION ALL SELECT '4. 函式只寫 discount_code（UPDATE 段沒有其他欄位）', (SELECT replace(p.prosrc, E'\r', '') LIKE '%SET discount_code = v_new_code,%updated_at = now()%' AND replace(p.prosrc, E'\r', '') NOT LIKE '%SET discount_amount%' AND replace(p.prosrc, E'\r', '') NOT LIKE '%final_price =%' FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'))
UNION ALL SELECT '5. 內含金額欄位前後比對與回滾', (SELECT replace(p.prosrc, E'\r', '') LIKE '%v_after_money IS DISTINCT FROM v_before_money%' FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'))
UNION ALL SELECT '6. 用 evaluate_discount_code 判斷、佣金已撥付防護', (SELECT replace(p.prosrc, E'\r', '') LIKE '%public.evaluate_discount_code(%' AND replace(p.prosrc, E'\r', '') LIKE '%settlement_status = ''paid''%' FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)'))
UNION ALL SELECT '7. 已結清守門觸發器仍掛在 orders 上', EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgname = 'trg_prevent_immutable_order_fields' AND t.tgrelid = 'public.orders'::regclass AND NOT t.tgisinternal)
UNION ALL SELECT '8. 佣金觸發器仍掛在 orders 上', EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgname = 'create_commission_on_order_updated' AND t.tgrelid = 'public.orders'::regclass AND NOT t.tgisinternal);

SELECT p.proname AS 函式, md5(replace(p.prosrc, E'\r', '')) AS 指紋,
       md5(replace(p.prosrc, E'\r', '')) = CASE p.proname WHEN 'update_paid_order_discount_v2' THEN '072ae35e8cbadaf141d3ee5cc5ff0d3f' WHEN 'prevent_immutable_order_fields_change' THEN '7ae4c310175709cc09642d3a1fe7a986' WHEN 'create_commission_record' THEN '4d20a51ca97a4e75692b363efd2d29be' WHEN 'sync_discount_code_used_count' THEN '8fa7ab81b5192361f05c941b11270f3c' WHEN 'evaluate_discount_code' THEN '2cb75f8d30f523323057e8901cec7731' WHEN 'update_order_fields_v1' THEN '281dd4b043ecf7204d331c1419be446b' WHEN 'validate_discount_code' THEN '30c2bde9ab95f1834f8efd9860c27249' END AS 既有函式未被修改
FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
WHERE n.nspname = 'public' AND p.proname IN ('update_paid_order_discount_v2', 'prevent_immutable_order_fields_change', 'create_commission_record', 'sync_discount_code_used_count', 'evaluate_discount_code', 'update_order_fields_v1', 'validate_discount_code')
ORDER BY p.proname;

SELECT md5(replace(p.prosrc, E'\r', '')) AS 新函式指紋 FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_referral_code_v1(uuid, timestamp with time zone, text, text, boolean, boolean)');
